import { isNutShape, shapeLabels, type DrawingDefinition } from './types.ts';

const ink = '#20252b';
const esc = (value: string) =>
  value.replace(
    /[&<>"']/g,
    (c) =>
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[
        c
      ]!,
  );
const number = (value: number) => Number(value.toFixed(3));
const line = (x1: number, y1: number, x2: number, y2: number, extra = '') =>
  `<line x1="${number(x1)}" y1="${number(y1)}" x2="${number(x2)}" y2="${number(y2)}" ${extra}/>`;
const label = (x: number, y: number, value: string, extra = '') =>
  `<text x="${number(x)}" y="${number(y)}" ${extra}>${esc(value)}</text>`;
const center = (x1: number, y1: number, x2: number, y2: number) =>
  line(x1, y1, x2, y2, 'class="axis"');

function horizontal(
  x1: number,
  x2: number,
  y: number,
  featureY: number,
  value: string,
) {
  return `<g class="dimension" data-dimension="${esc(value.split(' ')[0])}">${line(x1, featureY, x1, y + 6)}${line(x2, featureY, x2, y + 6)}${line(x1, y, x2, y, 'marker-start="url(#arrow)" marker-end="url(#arrow)"')}${label((x1 + x2) / 2, y - 7, value, 'text-anchor="middle" class="dim-label"')}</g>`;
}
function vertical(
  x: number,
  y1: number,
  y2: number,
  featureX: number,
  value: string,
) {
  return `<g class="dimension" data-dimension="${esc(value.split(' ')[0])}">${line(featureX, y1, x + 6, y1)}${line(featureX, y2, x + 6, y2)}${line(x, y1, x, y2, 'marker-start="url(#arrow)" marker-end="url(#arrow)"')}${label(x - 8, (y1 + y2) / 2, value, `text-anchor="middle" class="dim-label" transform="rotate(-90 ${number(x - 8)} ${number((y1 + y2) / 2)})"`)}</g>`;
}
const leader = (
  x: number,
  y: number,
  endX: number,
  endY: number,
  value: string,
) =>
  `<g class="dimension">${label(x, y - 8, value)}<path d="M${x} ${y}h35L${number(endX)} ${number(endY)}" marker-end="url(#arrow)"/></g>`;

function hexEnd(
  cx: number,
  cy: number,
  flats: number,
  bore?: number,
  nominal?: number,
) {
  const r = flats / Math.sqrt(3);
  const points = Array.from(
    { length: 6 },
    (_, i) =>
      `${number(cx + r * Math.cos(((30 + 60 * i) * Math.PI) / 180))},${number(cy + r * Math.sin(((30 + 60 * i) * Math.PI) / 180))}`,
  ).join(' ');
  return `<g data-view="end" class="outline"><polygon points="${points}"/><circle cx="${cx}" cy="${cy}" r="${number(flats / 2)}" class="fine"/>${bore ? `<circle cx="${cx}" cy="${cy}" r="${number(bore / 2)}"/>` : ''}${nominal && bore ? `<path class="fine" d="M${number(cx + nominal / 2)} ${cy}A${number(nominal / 2)} ${number(nominal / 2)} 0 1 1 ${number(cx + nominal / 4)} ${number(cy - (nominal * Math.sqrt(3)) / 4)}"/>` : ''}</g>${center(cx - r - 12, cy, cx + r + 12, cy)}${center(cx, cy - r - 12, cx, cy + r + 12)}`;
}

function sideHead(
  x: number,
  cy: number,
  width: number,
  flats: number,
  washer = false,
) {
  const corner = Math.min(5, width * 0.2, flats * 0.1),
    drop = corner * Math.tan((25 * Math.PI) / 180),
    top = cy - flats / 2,
    bottom = cy + flats / 2;
  return `<g class="outline" data-part="head"><path d="M${number(x + corner)} ${number(top)}H${number(x + width)}V${number(bottom)}H${number(x + corner)}L${x} ${number(bottom - drop)}V${number(top + drop)}Z"/><path class="fine" d="M${x} ${number(cy - flats / 4)}Q${number(x + width / 2)} ${number(cy - flats / 4 - corner)} ${number(x + width)} ${number(cy - flats / 4)}M${x} ${number(cy + flats / 4)}Q${number(x + width / 2)} ${number(cy + flats / 4 + corner)} ${number(x + width)} ${number(cy + flats / 4)}"/>${washer ? `<path d="M${number(x + width - 3)} ${number(top + corner)}h3v${number(flats - 2 * corner)}h-3Z"/>` : ''}</g>`;
}

function boltViews(
  definition: DrawingDefinition,
  length: number,
  thread: number,
) {
  const d = definition.dimensions;
  const scale = Math.min(450 / length, 100 / d.head_width!, 12);
  const flats = d.head_width! * scale,
    k = d.head_height! * scale,
    shaft = (d.diameter_max ?? d.diameter) * scale;
  const cy = 225,
    hx = 265,
    start = hx + k,
    end = start + length * scale,
    threadStart = end - thread * scale;
  const tip = Math.min(4, shaft * 0.13),
    root = shaft / 2 - Math.min(3.5, shaft * 0.13);
  const r = flats / Math.sqrt(3),
    endCx = 130;
  let body = `<g data-view="side">${sideHead(hx, cy, k, flats)}<g class="outline" data-part="shank"><path d="M${number(start)} ${number(cy - shaft / 2)}H${number(end - tip)}L${number(end)} ${number(cy - shaft / 2 + tip)}V${number(cy + shaft / 2 - tip)}L${number(end - tip)} ${number(cy + shaft / 2)}H${number(start)}"/></g><g class="fine" data-part="thread-convention">${line(threadStart, cy - root, end, cy - root)}${line(threadStart, cy + root, end, cy + root)}${line(threadStart, cy - shaft / 2, threadStart, cy + shaft / 2)}</g>${center(hx - 15, cy, end + 20, cy)}</g>`;
  body += hexEnd(endCx, cy, flats);
  body += horizontal(
    endCx - flats / 2,
    endCx + flats / 2,
    306,
    cy + r,
    `s ${d.head_width}`,
  );
  body += vertical(55, cy - r, cy + r, endCx, `e min ${d.across_corners_min}`);
  body += horizontal(hx, start, 305, cy + flats / 2, `k max ${d.head_height}`);
  body += horizontal(
    threadStart,
    end,
    332,
    cy + shaft / 2,
    `${definition.shape === 'hex-screw' ? 'b1' : 'b'} min ${number(thread)}`,
  );
  body += horizontal(start, end, 374, cy + shaft / 2, `L ${length}`);
  body += vertical(
    end + 35,
    cy - shaft / 2,
    cy + shaft / 2,
    end,
    `d ${d.diameter}`,
  );
  body += leader(220, 112, hx + 2, cy - flats / 2 + 2, '15°–30° chamfer');
  body += leader(
    Math.max(start + 80, end - 190),
    151,
    end - 1,
    cy - shaft / 2 + 2,
    definition.standard === 'IS 1364'
      ? 'Chamfered end'
      : 'Chamfered or sheared end',
  );
  body += `<g data-view="washer-face-option">${sideHead(110, 425, Math.min(Math.max(k, 15), 26), Math.min(Math.max(flats, 38), 54), true)}${center(98, 425, 110 + Math.min(Math.max(k, 15), 26) + 12, 425)}${label(130, 471, 'Washer face permissible', 'text-anchor="middle" class="caption"')}</g>`;
  body += label(
    510,
    439,
    shapeLabels[definition.shape].toUpperCase(),
    'text-anchor="middle" class="view-title"',
  );
  body += label(
    510,
    463,
    `Pitch P ${d.pitch} mm${definition.shape === 'hex-bolt' ? ` / thread tolerance +0 to ${number(2 * d.pitch!)} mm` : ''}`,
    'text-anchor="middle" class="caption"',
  );
  return body;
}

function nutSide(
  x: number,
  cy: number,
  thickness: number,
  flats: number,
  bore: number,
  major: number,
  fullBearing: boolean,
  id: string,
) {
  const top = cy - flats / 2,
    bottom = cy + flats / 2,
    c = Math.min(7, thickness * 0.2),
    drop = c * Math.tan((25 * Math.PI) / 180);
  const outline = fullBearing
    ? `M${x + c} ${top}H${x + thickness}V${bottom}H${x + c}L${x} ${bottom - drop}V${top + drop}Z`
    : `M${x + c} ${top}H${x + thickness - c}L${x + thickness} ${top + drop}V${bottom - drop}L${x + thickness - c} ${bottom}H${x + c}L${x} ${bottom - drop}V${top + drop}Z`;
  return `<g data-view="${id}"><defs><clipPath id="${id}-clip"><path d="${outline}"/></clipPath></defs><g clip-path="url(#${id}-clip)"><rect x="${x}" y="${cy + bore / 2}" width="${thickness}" height="${(flats - bore) / 2}" fill="url(#hatch)"/></g><g class="outline"><path d="${outline}" fill="none"/>${line(x + c, cy - bore / 2, x + thickness - c, cy - bore / 2)}${line(x + c, cy + bore / 2, x + thickness - c, cy + bore / 2)}<path class="fine" d="M${x} ${cy - major / 2}h${thickness}M${x} ${cy + major / 2}h${thickness}"/><path d="M${x} ${cy - major / 2}l${c} ${(major - bore) / 2}M${x} ${cy + major / 2}l${c} ${-(major - bore) / 2}"/>${line(x, cy - flats / 4, x + thickness, cy - flats / 4)}</g>${center(x - 15, cy, x + thickness + 15, cy)}</g>`;
}

function nutViews(definition: DrawingDefinition) {
  const d = definition.dimensions,
    scale = Math.min(120 / d.head_width!, 14);
  const flats = d.head_width! * scale,
    thickness = d.head_height! * scale;
  const bore = d.minor_diameter_max! * scale,
    major = d.diameter * scale,
    cy = 240,
    left = 110,
    mid = 390,
    cx = 735;
  const symbol = definition.shape === 'lock-nut' ? 'm1' : 'm';
  let body = nutSide(
    left,
    cy,
    thickness,
    flats,
    bore,
    major,
    false,
    'alternate-side',
  );
  body += nutSide(
    mid,
    cy,
    thickness,
    flats,
    bore,
    major,
    true,
    'full-bearing-side',
  );
  body += hexEnd(cx, cy, flats, bore, major);
  body += horizontal(
    left,
    left + thickness,
    350,
    cy + flats / 2,
    `${symbol} max ${d.head_height}`,
  );
  body += horizontal(
    mid,
    mid + thickness,
    350,
    cy + flats / 2,
    `${symbol} max ${d.head_height}`,
  );
  body += horizontal(
    cx - flats / 2,
    cx + flats / 2,
    350,
    cy + flats / Math.sqrt(3),
    `s ${d.head_width}`,
  );
  body += vertical(
    840,
    cy - flats / Math.sqrt(3),
    cy + flats / Math.sqrt(3),
    cx,
    `e min ${d.across_corners_min}`,
  );
  body += vertical(
    left + thickness + 35,
    cy - bore / 2,
    cy + bore / 2,
    left + thickness,
    `d ${d.diameter}`,
  );
  body += vertical(
    mid + thickness + 35,
    cy - bore / 2,
    cy + bore / 2,
    mid + thickness,
    `d ${d.diameter}`,
  );
  body += leader(350, 111, mid + thickness, cy - flats / 2, '15°–30° chamfer');
  body += label(
    left + thickness / 2,
    395,
    'Alternate shape',
    'text-anchor="middle" class="caption"',
  );
  body += label(
    left + thickness / 2,
    414,
    'Chamfered thread start',
    'text-anchor="middle" class="caption"',
  );
  body += label(
    mid + thickness / 2,
    395,
    'Full bearing surface',
    'text-anchor="middle" class="caption"',
  );
  body += label(
    cx,
    416,
    shapeLabels[definition.shape].toUpperCase(),
    'text-anchor="middle" class="view-title"',
  );
  body += label(
    450,
    462,
    `${symbol} ${d.head_height_min}–${d.head_height_max} mm / minor diameter ${d.minor_diameter_min}–${d.minor_diameter_max} mm / P ${d.pitch} mm`,
    'text-anchor="middle" class="caption"',
  );
  return `<g data-part="nut">${body}</g>`;
}

